const precomputeFantasyCaches=onSchedule({schedule:'every 3 hours',timeoutSeconds:540,memory:'512MiB',maxInstances:1},async()=>{const snap=await db.collectionGroup('fantasy').get(),docs=snap.docs.filter(d=>d.id==='state'&&d.data()?.state),memo=new Map();let ok=0,failed=0;for(let i=0;i<docs.length;i+=8){const chunk=docs.slice(i,i+8);await Promise.all(chunk.map(async d=>{try{await refreshStateDoc(d,true,memo);ok++}catch(e){failed++;console.error('Scheduled cache refresh failed',d.ref.path,e)}}))}console.log('Fantasy derived cache refresh complete',{users:docs.length,ok,failed})});
